$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$modulePath = Join-Path $pkg "ahos\workforce_execution.py"
$testPath = Join-Path $pkg "tests\test_workforce_execution.py"
$backlogPath = Join-Path $pkg "AHOS_BACKLOG.json"
$python = Join-Path $root ".venv\Scripts\python.exe"

if (-not (Test-Path $backlogPath)) { throw "AHOS_BACKLOG.json not found." }
if (-not (Test-Path $python)) { throw "Python venv not found." }

[IO.File]::WriteAllBytes($modulePath, [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($testPath, [Convert]::FromBase64String(""))

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
if (-not ($b.tasks | Where-Object { $_.id -eq "AHOS-024" })) {
    $b.tasks += [pscustomobject]@{
        id = "AHOS-024"
        title = "Connect virtual employees to task routing and QA lifecycle"
        status = "pending"
        risk = "low"
        authority = "B"
        requires_owner_approval = $false
        task = "Add deterministic virtual-workforce dispatch: capability matching, single-worker task leases, owner-approval gates for paid/external/destructive/secret-touching work, worker completion, QA handoff, and final QA completion. No LLM or network calls."
    }
    [IO.File]::WriteAllText(
        $backlogPath,
        ($b | ConvertTo-Json -Depth 12),
        (New-Object System.Text.UTF8Encoding($false))
    )
}

Write-Host "=== AHOS-024 WORKFORCE TASK ROUTER ==="
Write-Host "Connecting virtual workers to assignment + QA lifecycle."
Write-Host "NO network calls. NO OpenAI API calls."

$oldPythonPath = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg
    & $python -m pytest -q
    $testExit = $LASTEXITCODE
} finally {
    Pop-Location
    $env:PYTHONPATH = $oldPythonPath
}
if ($testExit -ne 0) { throw "AHOS-024 tests failed." }

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
$t = $b.tasks | Where-Object { $_.id -eq "AHOS-024" } | Select-Object -First 1
$t.status = "completed"
if ($t.PSObject.Properties.Name -contains "completed_at") {
    $t.completed_at = [DateTime]::UtcNow.ToString("o")
} else {
    $t | Add-Member -NotePropertyName completed_at -NotePropertyValue ([DateTime]::UtcNow.ToString("o"))
}
[IO.File]::WriteAllText(
    $backlogPath,
    ($b | ConvertTo-Json -Depth 12),
    (New-Object System.Text.UTF8Encoding($false))
)

git -C $ws add ahos_core/ahos/workforce_execution.py ahos_core/tests/test_workforce_execution.py ahos_core/AHOS_BACKLOG.json
git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "feat(ahos): connect virtual workforce task routing"
if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

git -C $ws push origin HEAD
if ($LASTEXITCODE -ne 0) { throw "git push failed." }

Write-Host ""
Write-Host "=== AHOS-024 COMPLETE ==="
Write-Host "Full AHOS tests: PASS"
Write-Host "Backlog: AHOS-024 -> completed"
Write-Host "Git push: PASS"
Write-Host "Worker routing: ENABLED"
Write-Host "QA handoff: ENABLED"
Write-Host "Paid/external/destructive/secret work: OWNER APPROVAL REQUIRED"
Write-Host "Network calls: 0"
Write-Host "OpenAI API calls: 0"
